export default function next({ events, previousState }) {
  if (!Array.isArray(events)) throw Error("Invalid events");
  const index = previousState?.index ?? 0;
  if (!Number.isInteger(index) || index < 0 || index > events.length)
    throw Error("Invalid event index");
  if (index === events.length) return { state: { index }, more: false, id: "unused", count: index };
  const id = events[index]?.recordId;
  if (typeof id !== "string" || !id) throw Error("Missing automation record ID");
  return { state: { index: index + 1 }, more: true, id, count: index };
}

