export default function prepare({ record, background, id }) {
  if (
    record?.id !== id ||
    !record.fields ||
    typeof record.fields.Briefing !== "string" ||
    !record.fields.Briefing.trim()
  )
    throw Error("Record briefing missing or mismatched");
  if (!background?.id || !background.fields || !Object.keys(background.fields).length)
    throw Error("Background information missing");
  return {
    input: [
      {
        role: "user",
        content: [
          {
            type: "input_text",
            text:
              "Create an engaging Instagram caption for the following briefing. Use the target audience and preferred communication style in the background. Include a clear call to action. Output only the caption.\nBriefing: " +
              record.fields.Briefing +
              "\nBackground: " +
              JSON.stringify(background.fields),
          },
        ],
      },
    ],
  };
}

