export default function prepare({ response, id }) {
  if (response?.status !== "completed" || !Array.isArray(response.output))
    throw Error("Caption generation failed");
  const text = response.output
    .flatMap((x) => x.content || [])
    .filter((x) => x.type === "output_text")
    .map((x) => x.text)
    .join("\n")
    .trim();
  if (!text) throw Error("Empty caption");
  return { records: [{ id, fields: { SoMe_Text_KI: text, Posten: false, Werbeanzeige: false } }] };
}

