export default function confirm({ records, expectedId }) {
  if (
    !Array.isArray(records) ||
    records.length !== 1 ||
    typeof records[0]?.id !== "string" ||
    !records[0].id ||
    (expectedId && records[0].id !== expectedId)
  )
    throw Error("Airtable did not confirm the expected record");
  return { id: records[0].id };
}
